1	package cli
2	
3	import (
4		"encoding/binary"
5		"errors"
6		"fmt"
7		"math"
8		"os"
9		"strings"
10		"sync"
11		"unicode"
12	
13		entirebrain "github.com/ashtom/entire-brain"
14	)
15	
16	// Embedder turns text into a unit-length vector for semantic recall. It is the
17	// Phase D abstraction boundary: the bundled backend is a pure-Go Model2Vec
18	// static model (staticEmbedder), but a transformer bi-encoder (ONNX) or a
19	// provider-shelled embedder can drop in behind this interface without touching
20	// the ranking path, once the eval harness shows the static model leaves recall
21	// headroom. Embed returns a slice of length Dim(); input that tokenizes to
22	// nothing (empty/whitespace-only) returns the zero vector, which callers treat
23	// as "no signal". Unknown words map to [UNK] and so still yield a non-zero
24	// vector.
25	type Embedder interface {
26		Embed(text string) []float32
27		Dim() int
28		// ID identifies the model + revision, used to invalidate cached fact
29		// vectors when the backend changes.
30		ID() string
31	}
32	
33	// staticEmbedder is a Model2Vec static embedding table: tokenize (BERT
34	// WordPiece) -> gather per-token vectors -> mean-pool -> L2-normalize. The
35	// matrix is int8 per-column quantized; rows are dequantized on gather, which
36	// keeps only ~the int8 table resident and is cheap since each text touches only
37	// a handful of tokens.
38	type staticEmbedder struct {
39		id      string
40		dim     int
41		vocab   map[string]int32
42		matrix  []int8    // vocab*dim, row-major
43		scales  []float32 // len dim, per-column dequant scale
44		unkID   int32
45		cont    string // WordPiece continuation prefix, e.g. "##"
46		lower   bool
47		strip   bool
48		chinese bool
49	}
50	
51	const embedModelMagic = "EBM1"
52	
53	// maxWordPieceChars matches BERT's max_input_chars_per_word: a token longer
54	// than this is emitted as [UNK] rather than greedily decomposed.
55	const maxWordPieceChars = 100
56	
57	func loadStaticEmbedder(raw []byte) (*staticEmbedder, error) {
58		r := &byteReader{b: raw}
59		if string(r.take(4)) != embedModelMagic {
60			return nil, errors.New("embed model: bad magic")
61		}
62		if v := r.u32(); v != 1 {
63			return nil, fmt.Errorf("embed model: unsupported version %d", v)
64		}
65		id := string(r.take(int(r.u16())))
66		dim := int(r.u32())
67		vocabSize := int(r.u32())
68		if dtype := r.u32(); dtype != 1 {
69			return nil, fmt.Errorf("embed model: unsupported dtype %d", dtype)
70		}
71		flags := r.u32()
72		unkID := int32(r.u32())
73		cont := string(r.take(int(r.u16())))
74		if r.err != nil {
75			return nil, fmt.Errorf("embed model header: %w", r.err)
76		}
77		if dim <= 0 || vocabSize <= 0 {
78			return nil, errors.New("embed model: empty dim/vocab")
79		}
80		if unkID < 0 || int(unkID) >= vocabSize {
81			return nil, fmt.Errorf("embed model: unkID %d out of range [0,%d)", unkID, vocabSize)
82		}
83		// Preflight the header sizes against the actual file length before any
84		// allocation: a corrupt/malformed header could otherwise request a giant
85		// vocab map / scales / matrix (or overflow vocabSize*dim) before take()
86		// discovers the truncation, defeating the graceful degrade-to-lexical path.
87		// The file is an upper bound on every section, and dividing avoids computing
88		// the (potentially overflowing) products: scales need dim*4 bytes, the vocab
89		// needs ≥vocabSize*2 (a uint16 length per token), the matrix vocabSize*dim.
90		if n := len(raw); dim > n/4 || vocabSize > n/2 || vocabSize > n/dim {
91			return nil, fmt.Errorf("embed model: header sizes (dim=%d vocab=%d) exceed file length %d", dim, vocabSize, n)
92		}
93		vocab := make(map[string]int32, vocabSize)
94		for i := 0; i < vocabSize; i++ {
95			tok := string(r.take(int(r.u16())))
96			if r.err != nil {
97				return nil, fmt.Errorf("embed model vocab[%d]: %w", i, r.err)
98			}
99			vocab[tok] = int32(i)
100		}
101		scales := make([]float32, dim)
102		for i := range scales {
103			scales[i] = math.Float32frombits(r.u32())
104		}
105		matrix := make([]int8, vocabSize*dim)
106		mb := r.take(len(matrix))
107		if r.err != nil {
108			return nil, fmt.Errorf("embed model matrix: %w", r.err)
109		}
110		for i, b := range mb {
111			matrix[i] = int8(b)
112		}
113		return &staticEmbedder{
114			id: id, dim: dim, vocab: vocab, matrix: matrix, scales: scales,
115			unkID: unkID, cont: cont,
116			lower:   flags&1 != 0,
117			strip:   flags&2 != 0,
118			chinese: flags&4 != 0,
119		}, nil
120	}
121	
122	func (e *staticEmbedder) Dim() int   { return e.dim }
123	func (e *staticEmbedder) ID() string { return e.id }
124	
125	func (e *staticEmbedder) Embed(text string) []float32 {
126		out := make([]float32, e.dim)
127		ids := e.tokenize(text)
128		if len(ids) == 0 {
129			return out
130		}
131		for _, id := range ids {
132			base := int(id) * e.dim
133			row := e.matrix[base : base+e.dim]
134			for d := 0; d < e.dim; d++ {
135				out[d] += float32(row[d]) * e.scales[d]
136			}
137		}
138		inv := 1.0 / float32(len(ids))
139		var norm float64
140		for d := range out {
141			out[d] *= inv
142			norm += float64(out[d]) * float64(out[d])
143		}
144		if norm > 0 {
145			s := float32(1.0 / math.Sqrt(norm))
146			for d := range out {
147				out[d] *= s
148			}
149		}
150		return out
151	}
152	
153	// tokenize replicates BERT BertNormalizer + BertPreTokenizer + WordPiece so the
154	// gathered token ids match the ids the model was distilled against (validated
155	// by the golden-parity test).
156	func (e *staticEmbedder) tokenize(text string) []int32 {
157		var ids []int32
158		for _, word := range e.preTokenize(e.normalize(text)) {
159			ids = e.wordPiece(word, ids)
160		}
161		return ids
162	}
163	
164	// normalize applies clean_text, handle_chinese_chars, lowercase, and accent
165	// stripping. Accent stripping folds Latin precomposed letters to their base
166	// (covering the realistic English-plus-names corpus) rather than pulling in a
167	// full Unicode NFD dependency.
168	func (e *staticEmbedder) normalize(text string) string {
169		var b strings.Builder
170		b.Grow(len(text))
171		for _, r := range text {
172			if r == 0 || r == 0xFFFD || (unicode.IsControl(r) && r != '\t' && r != '\n' && r != '\r') {
173				continue // clean_text: drop nulls and control chars
174			}
175			if unicode.IsSpace(r) {
176				b.WriteByte(' ')
177				continue
178			}
179			if e.chinese && isCJK(r) {
180				b.WriteByte(' ')
181				b.WriteRune(r)
182				b.WriteByte(' ')
183				continue
184			}
185			if e.lower {
186				r = unicode.ToLower(r)
187			}
188			if e.strip {
189				if folded, ok := stripAccent(r); ok {
190					if folded != 0 {
191						b.WriteRune(folded)
192					}
193					continue
194				}
195			}
196			b.WriteRune(r)
197		}
198		return b.String()
199	}
200	
201	// preTokenize splits on whitespace and isolates punctuation into its own
202	// tokens, matching BertPreTokenizer.
203	func (e *staticEmbedder) preTokenize(text string) []string {
204		var out []string
205		for _, field := range strings.Fields(text) {
206			var cur strings.Builder
207			for _, r := range field {
208				if isBertPunct(r) {
209					if cur.Len() > 0 {
210						out = append(out, cur.String())
211						cur.Reset()
212					}
213					out = append(out, string(r))
214					continue
215				}
216				cur.WriteRune(r)
217			}
218			if cur.Len() > 0 {
219				out = append(out, cur.String())
220			}
221		}
222		return out
223	}
224	
225	// wordPiece greedily decomposes one word into the longest matching vocab
226	// pieces (continuation pieces carry the cont prefix), appending their ids. A
227	// word that cannot be fully covered contributes a single [UNK].
228	func (e *staticEmbedder) wordPiece(word string, ids []int32) []int32 {
229		runes := []rune(word)
230		if len(runes) == 0 {
231			return ids
232		}
233		if len(runes) > maxWordPieceChars {
234			return append(ids, e.unkID)
235		}
236		start := 0
237		var pieces []int32
238		for start < len(runes) {
239			end := len(runes)
240			found := int32(-1)
241			for start < end {
242				sub := string(runes[start:end])
243				if start > 0 {
244					sub = e.cont + sub
245				}
246				if id, ok := e.vocab[sub]; ok {
247					found = id
248					break
249				}
250				end--
251			}
252			if found < 0 {
253				return append(ids, e.unkID) // whole word is [UNK]
254			}
255			pieces = append(pieces, found)
256			start = end
257		}
258		return append(ids, pieces...)
259	}
260	
261	func isCJK(r rune) bool {
262		return (r >= 0x4E00 && r <= 0x9FFF) || (r >= 0x3400 && r <= 0x4DBF) ||
