1	package cli
2	
3	import (
4		"math"
5		"sort"
6		"strings"
7	)
8	
9	// rrfK is the Reciprocal Rank Fusion constant. 60 is the canonical value from
10	// the original RRF paper and what hybrid-search systems (e.g. qmd) use; it
11	// damps the influence of a single retriever's top ranks so neither the lexical
12	// nor the semantic list can unilaterally dominate the fusion.
13	const rrfK = 60.0
14	
15	// semanticReranker holds the embedder and a cache of fact vectors. Fact ids are
16	// content-derived, so a vector is valid for the life of the fact: the in-memory
17	// cache makes an eval over many queries embed each fact at most once, and an
18	// optional disk store (recall/brief) carries vectors across CLI invocations.
19	type semanticReranker struct {
20		e       Embedder
21		cache   map[string][]float32
22		store   *embedStore     // nil => in-memory only (eval, tests)
23		touched map[string]bool // ids seen this run; nil unless disk-backed
24		dirty   bool            // a new vector was embedded this run
25	}
26	
27	// newSemanticReranker returns nil when no embedder is available, so callers can
