13		entirebrain "github.com/ashtom/entire-brain"
14	)
15	
16	// Embedder turns text into a unit-length vector for semantic recall. It is the
17	// Phase D abstraction boundary: the bundled backend is a pure-Go Model2Vec
18	// static model (staticEmbedder), but a transformer bi-encoder (ONNX) or a
19	// provider-shelled embedder can drop in behind this interface without touching
20	// the ranking path, once the eval harness shows the static model leaves recall
21	// headroom. Embed returns a slice of length Dim(); input that tokenizes to
22	// nothing (empty/whitespace-only) returns the zero vector, which callers treat
23	// as "no signal". Unknown words map to [UNK] and so still yield a non-zero
24	// vector.
25	type Embedder interface {
26		Embed(text string) []float32
27		Dim() int
28		// ID identifies the model + revision, used to invalidate cached fact
29		// vectors when the backend changes.
30		ID() string
31	}
32	
33	// staticEmbedder is a Model2Vec static embedding table: tokenize (BERT
34	// WordPiece) -> gather per-token vectors -> mean-pool -> L2-normalize. The
35	// matrix is int8 per-column quantized; rows are dequantized on gather, which
36	// keeps only ~the int8 table resident and is cheap since each text touches only
37	// a handful of tokens.
38	type staticEmbedder struct {
39		id      string
40		dim     int
41		vocab   map[string]int32
