267	// ids: that is the agent's judgment during distillation, handled separately.
268	func upsertFact(records []factRecord, incoming factRecord) []factRecord {
269		for i := range records {
270			if records[i].ID != incoming.ID {
271				continue
272			}
273			records[i].Provenance = unionFactAnchors(records[i].Provenance, incoming.Provenance)
274			if incoming.UpdatedAt.After(records[i].UpdatedAt) {
275				records[i].UpdatedAt = incoming.UpdatedAt
276			}
277			return records
278		}
279		return append(records, incoming)
280	}
281	
282	// unionFactAnchors appends anchors from b that are not already present in a,
283	// preserving order. Anchors are compared on their identifying fields so the
284	// same source turn is never recorded twice.
285	func unionFactAnchors(a, b []factAnchor) []factAnchor {
